INSERT INTO public.scraper_sources (id, source_name, society, base_url, default_event_type, pagination_type, pagination_template, max_pages_hint, detail_is_multipage, active, extraction_instructions) VALUES
  (147, 'AAP National Conference & Exhibition', 'AAP', 'https://aapexperience.org/future-dates/', 'conference', 'single_page', NULL, 1, FALSE, TRUE, 'aapexperience.org/future-dates/ lists blocks ''year / city / venue / dates''; the first not-yet-finished block is the edition. Cloudflare throttles plain HTTP on some paths; registration page is the previous edition until switched, so fees are gated on ''the <year> National Conference''. Abstract deadline is the ''Abstract Submission Deadline'' line on the call-for-educational-content page, not the session-proposal date.'),
  (148, 'AMWC (Aesthetic & Anti-Aging Medicine World Congress)', 'AMWC', 'https://www.amwc-conference.com/', 'conference', 'single_page', NULL, 1, FALSE, TRUE, 'Informa Next.js page (server-rendered). Dates from JSON-LD but widened to the visible header range (1-3 April). Fees on /register/ as ''<pass> / struck price / current price / Offer ends <day month>''; abstract deadlines (oral/poster) have no year.'),
  (149, 'BAD Annual Meeting', 'BAD', 'https://badannualmeeting.co.uk/', 'conference', 'single_page', NULL, 1, FALSE, TRUE, 'badannualmeeting.co.uk home slider gives ''Liverpool Experience Campus 29 June - 1 July 2027''; abstract deadlines on /abstracts/. /registration/ stays on the previous edition until registration opens (Feb 2027), so no tiers.'),
  (150, 'BSPED Annual Meeting', 'BSPED', 'https://www.bsped.org.uk/meetings/forthcoming-meetings/', 'conference', 'single_page', NULL, 1, FALSE, TRUE, 'bsped.org.uk/meetings/forthcoming-meetings/ lists title/date/city only. All details sit on an EventsForce microsite with robots Disallow /, deliberately not fetched.'),
  (151, 'Digital Health Rewired', 'Digital Health Rewired', 'https://digitalhealthrewired.com/', 'conference', 'single_page', NULL, 1, FALSE, TRUE, 'ASP.events site; JSON-LD Event gives dates and the NEC Birmingham venue. Fees are cards on /tickets-pricing (free public/third sector, GBP +VAT private and start-up); speaker call on /call-speakers.'),
  (152, 'ACR Convergence', 'ACR', 'https://rheumatology.org/meetings/acr-convergence/', 'conference', 'single_page', NULL, 1, FALSE, TRUE, 'rheumatology.org Next.js page: ''Date:'' and ''Location:'' label lines; fees are Member/Nonmember x Early/General x In Person Plus/In Person text grids on /annual-meeting-registration (expired early rates skipped). CPD points not recorded (182.75 total).'),
  (153, 'ATS International Conference', 'ATS', 'https://site.thoracic.org/conference', 'conference', 'single_page', NULL, 1, FALSE, TRUE, 'site.thoracic.org/conference home ends with ''Attend ATS 2027 / May 14-19, 2027 / New Orleans, LA''. No 2027 fees yet. Abstract call page says deadline passed plus the late-breaking date.'),
  (154, 'EULAR European Congress of Rheumatology', 'EULAR', 'https://congress.eular.org/', 'conference', 'single_page', NULL, 1, FALSE, TRUE, 'congress.eular.org (Congress only, eular.org events are source 134). Home ''EULAR 2027 | 9 - 12 June 2027''; fee grid on /congress-registration (early until 31 March, regular from 1 April, EUR incl. VAT); abstract key dates on /abstractgeneralinfo.')
